syntax = 'proto3';

message ControllableLoadReq {
  optional string sn = 1;
  optional int32 remain_power = 2;
  optional uint32 schedule_id = 3;
}

message ControllableLoadInfo {
  optional string sn = 1;
  optional bool enabled = 2;
  optional bool scheduling = 3;
}

